-- ---------- ขั้น D: ตรวจหลังรัน (ต้องได้ตามที่เขียนในวงเล็บ) ----------
SELECT 'ดีลไม่มีรหัส PJ (ต้อง 0)' AS เรื่อง, COUNT(*) AS ค่า FROM pipeline_items WHERE project_code IS NULL
UNION ALL SELECT 'งานประมูลไม่มีรหัส PJ (ต้อง 0)', COUNT(*) FROM project_assignments WHERE project_code IS NULL
UNION ALL SELECT 'รหัส PJ ดีลซ้ำกัน (ต้อง 0)', COUNT(*) - COUNT(DISTINCT project_code) FROM pipeline_items
UNION ALL SELECT 'งานประมูลที่รหัสไม่ตรงดีลคู่ (ต้อง 0)', COUNT(*) FROM project_assignments pa LEFT JOIN pipeline_items pi ON pi.project_code = pa.project_code AND pi.source_type = 'ebidding' WHERE pi.id IS NULL
UNION ALL SELECT 'ดีลแหล่งที่มาว่าง (ต้อง 0)', COUNT(*) FROM pipeline_items WHERE source_type = ''
UNION ALL SELECT 'ดีล self_sourced (ต้อง 821)', COUNT(*) FROM pipeline_items WHERE source_type = 'self_sourced'
UNION ALL SELECT 'ดีล ebidding (ต้อง 65)', COUNT(*) FROM pipeline_items WHERE source_type = 'ebidding'
UNION ALL SELECT 'ประวัติดีลทั้งหมด (ต้อง 1308 + ที่เพิ่มหลังเกิดเหตุ)', COUNT(*) FROM pipeline_item_history
UNION ALL SELECT 'ตัวนับรหัส PJ (ต้อง 205 วัน)', COUNT(*) FROM project_code_counters
UNION ALL SELECT 'ตัวนับวันนี้ 261020 (ต้อง 1)', COALESCE((SELECT last_number FROM project_code_counters WHERE period='261020'),0);
